window.addEventListener('DOMContentLoaded',() => {function setCookieConsent(name,value,options) {const opts = {path: "/",...options };if (navigator.cookieEnabled) {let cookieText = encodeURIComponent(name) + "=" + encodeURIComponent(value);if (opts.days && typeof opts.days === "number") {const date = new Date();date.setTime(date.getTime() + (opts.days * 24 * 60 * 60 * 1000));cookieText += ";expires=" + date.toUTCString();}if (opts.path) {cookieText += ";path=" + opts.path;}if (opts.domain) {cookieText += ";domain=" + opts.domain;}cookieText += ";SameSite=Lax";document.cookie = cookieText;}}function getCookie(name) {if (document.cookie !== "") {const cookies = document.cookie.split(/;*/);for (let cookie of cookies) {const [cookieName,cookieVal] = cookie.split("=");if (cookieName === decodeURIComponent(name)) {return decodeURIComponent(cookieVal);}}}return undefined;}function initCookieConsent() {const box = document.getElementById('cookie-box');if (!box) return;const accepted = getCookie("wpex_cookie_accepted");if (accepted !== 'yes') {box.classList.remove('cookie-hidden');}const button = box.querySelector('.extra-cookie-accept-button');if (button) {let expireTime = parseInt(button.getAttribute('data-expire') || '30',10);button.addEventListener('click',function(e) {e.preventDefault();setCookieConsent("wpex_cookie_accepted","yes",{days: expireTime,path: "/" });box.style.transition = "opacity 0.4s ease,transform 0.4s ease";box.style.opacity = "0";box.style.transform = "translateY(20px)";setTimeout(() => {box.classList.add('cookie-hidden');},400);});}}initCookieConsent();});